                            .tooltip("Set how every selected story will be sent")
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.bulk_mode_menu = match this.bulk_mode_menu {
                                    Some(_) => None,
                                    None => Some(0),
                                };
                                cx.notify();
                            })),
                    ),
                )
